1	/**
2	 * VR-1: `nexus verify`, the verdict on a change that Nexus did not necessarily make: a working tree against a commit,
3	 * or one commit against another. No model is involved.
4	 *
5	 * Both sides are materialised into scratch directories (the caller's checkout is never written), the verifier is taken
6	 * from the operator or discovered in the BASE tree (the head is the change under test and cannot choose its own judge),
7	 * it is run on the base and on the head, and the outcome is derived by the same rules the agent applies to its own
8	 * work: this module re-composes captureChangeBaselineImpl / judgeIndependenceImpl (core/completion_oracle.ts) and the
9	 * evidence built in core/spine_handlers.ts, and derives the outcome with outcomeFromEvidence. The project type-checks
10	 * run on both sides as the agent's oracle runs them (core/typecheck_evidence.ts), and every changed file that defines
11	 * or weakens the verification is a guard finding, classified under the BASE tree's policy.
12	 *
13	 * Where each thing is read: the guard reads both trees before any repository code has run in them; the verifier runs in
14	 * `base` and `head`; the type-checks run in copies of their own (`base-typecheck`, `head-typecheck`), because a checker
15	 * may write build output; and the head is judged on `head-pristine`, a copy nothing has run in.
16	 *
17	 * Who can write what: every process started here is sandboxed by default, so the head cannot write the scratch Git
18	 * state beside its tree. `--sandbox none` is an explicit operator opt-out for trusted changes only.
19	 *
20	 * Authority: the request names only what to compare. Everything that can raise the verdict (the verifier command, its
21	 * approval, the declared deliverables, the deadline) comes from the operator context. Anything that cannot be fully
22	 * evaluated lowers the verdict with a reason that names it; nothing here raises one.
23	 */
24	import fs from "node:fs";
25	import { Buffer } from "node:buffer";
26	import os from "node:os";
27	import path from "node:path";
28	import { spawnSync } from "node:child_process";
29	import { createHash, randomUUID } from "node:crypto";
30	import { getBuildIdentity } from "../build_identity.js";
31	import { trustedGitArgs } from "../git.js";
32	import { isSandboxAvailable, quoteForShell, wrapSandboxedCommand } from "../sandbox.js";
33	import { sandboxDenialEvent } from "../sandbox_events.js";
34	import { SecurityManager, conditionalConfigChanged, isConditionalConfig, neutersTests } from "../security.js";
35	import {
36	  MAX_TEST_BYTES, MAX_TEST_FILES, SKIP_DIRS, buildVerifierEnvironment, describeVerifier, discoverTypechecks, discoverVerifier, discoverWorkspaceTestFiles, hasExecutedTests, isFilteredVerifierCommand, isTestPath, isVerifierDeliverableBound,
37	  runVerifierShell, typecheckMode, verifierTimeoutSecs, workspaceRuntimeFiles, type DiscoveredTypecheck, type TimedExecutor,
38	} from "../tester.js";
39	import { formatDiagnosticForOutput, safeTerminal } from "../ui.js";
40	import {
41	  VERIFY_RESULT_SCHEMA_VERSION, verifyExitCode, verifyExitNameFor, verifyVerdictFor,
42	  type VerifyGuard, type VerifyGuardFinding, type VerifyJsonResult, type VerifyReason, type VerifyRunRecord, type VerifySandbox, type VerifySandboxEngine, type VerifyTreeRef, type VerifyVerifierRecord,
43	} from "../verify_contract.js";
44	import { GitError, UntrustedCheckoutError, git, printable } from "../worktrunk/git.js";
45	import {
46	  isInlineProgramVerifier, judgeWithoutCopy, prepareBaselineTestsCopy, requiresWorkspaceVerifierDefinitionBinding, snapshotTests,
47	  snapshotVerifierDefinitionWithReason, testsChangedSince, verifierDefinitionChangedSince, type ChangeBaseline, type Independence,
48	} from "./independent_check.js";
49	import { classifyTestEdit } from "./regression_obligations.js";
50	import { NOT_RUN_REVIEW, reviewEvidence, type CompletedReview } from "./verify_review.js";
51	import type { TypecheckEvidence, VerificationEvidence } from "./turn.js";
52	import { captureTypecheckBaseline, collectTypecheckEvidence, typecheckNotApplicable, typecheckProjectKey, worstTypecheckBlock } from "./typecheck_evidence.js";
53	import { outcomeFromEvidence } from "./verification_outcome.js";
54	
55	/** What to compare. Nothing here can raise the verdict, so this is the part a remote caller may supply. */
56	export interface VerifyRequest {
57	  /** The top of a Git working tree. */
58	  worktree: string;
59	  /** The commit the change starts from (default `HEAD`). */
60	  base?: string;
61	  /** The commit that holds the change; absent to verify the working tree. */
62	  head?: string;
63	}
64	
65	/** What only the operator (the launcher's command line) decides. */
66	export interface VerifyOperatorContext {
67	  /** The operator's own verifier command; absent to discover one in the base tree. */
68	  verifierCommand?: string;
69	  /** Approve whatever verifier is discovered (`--yes`). */
70	  approveDiscoveredVerifier?: boolean;
71	  /** Approve the discovered verifier with exactly this digest (`--approve-verifier`). */
72	  approvedVerifierDigest?: string;
73	  /** Workspace-relative product files the change is meant to deliver. */
74	  deliverables?: readonly string[];
75	  /** Workspace-relative verification files whose edit the operator approves (`--approve-verification-edit`). */
76	  approvedVerificationEdits?: readonly string[];
77	  /** Deadline of each verifier run, and of each side's type-checks, in seconds (default: NEXUS_VERIFIER_TIMEOUT_SECS, else 300). */
78	  timeoutSecs?: number;
79	  /** Lower bound override for the test-file snapshot, used by bounded fixtures in tests; never larger than the product's bound. */
80	  testFileLimit?: number;
81	  /** Confine every process started on repository content. Absent: use `auto`; `none` is an explicit trusted-input opt-out. */
82	  sandbox?: VerifySandboxRequest;
83	  /** Aborted to interrupt: acted on between child processes. */
84	  signal?: AbortSignal;
85	  /** Progress lines for a person (never part of the result). */
86	  onProgress?: (message: string) => void;
87	}
88	
89	/** Sandbox policy. `auto` is the default; `none` is an explicit operator opt-out. */
90	export interface VerifySandboxRequest {
91	  /** `auto`: Bubblewrap when it is usable, else Docker. */
92	  engine: "auto" | VerifySandboxEngine | "none";
93	  /** Let the confined processes use the network (`--sandbox-network`). Off unless true: no environment setting turns it on. */
94	  network?: boolean;
95	}
96	
97	/** The request or the options cannot be acted on: not a working tree, a ref that names no commit, a bad path. */
98	export class VerifyUsageError extends Error {
99	  constructor(message: string) {
100	    super(message);
101	    this.name = "VerifyUsageError";
102	  }
103	}
104	
105	export class VerifyInterrupted extends Error {
106	  constructor() {
107	    super("interrupted");
108	    this.name = "VerifyInterrupted";
109	  }
110	}
111	
112	/** Largest tree materialised: files and total bytes. A larger tree is BLOCKED, never verified in part. */
113	export const VERIFY_MAX_TREE_FILES = 20_000;
114	export const VERIFY_MAX_TREE_BYTES = 512 * 1024 * 1024;
115	/** Deadline of each Git command that reads or writes a whole tree, and of each small one. */
116	const GIT_TREE_TIMEOUT_MS = 120_000;
117	const GIT_TIMEOUT_MS = 30_000;
118	const GIT_LISTING_BUFFER = 64 * 1024 * 1024;
119	/** Dependency directories of the caller's checkout linked into the scratch trees, so both sides run with the same installed packages. */
120	const DEPENDENCY_DIRS: readonly string[] = ["node_modules", "vendor", ".venv", "venv"];

