1	/**
2	 * VR-1: the machine contract of `nexus verify`: the verdicts, the process exit codes and the JSON document `--json`
3	 * prints (the same document `--receipt <file>` writes). docs/USER_MANUAL.md documents the exit codes from the table
4	 * below and test/verify_command.test.ts fails when the manual falls behind. The published schema
5	 * (docs/protocol/verify-result-v3.schema.json) is generated from the types here by scripts/gen_verify_result_schema.mjs,
6	 * so they are plain data (no functions, no index signatures); test/verify_schema.test.ts fails when it falls behind.
7	 */
8	import type { EngineeringOutcome, TypecheckEvidence, VerificationEvidence } from "./core/turn.js";
9	import type { TypecheckBaselineRecord } from "./core/typecheck_evidence.js";
10	import type { EvidenceOutcomeReason } from "./core/verification_outcome.js";
11	import type { VerificationClass, VerificationMode } from "./security.js";
12	import type { TypecheckMode } from "./tester.js";
13	import type { SandboxDenialEvent } from "./sandbox_events.js";
14	
15	/**
16	 * Version of the document `nexus verify --json` prints. Adding an optional member keeps the version; removing or
17	 * renaming a member, or changing a member's type or meaning, bumps it. Every change is recorded in
18	 * docs/protocol/VERIFY_RESULT_VERSIONS.json.
19	 */
20	export const VERIFY_RESULT_SCHEMA_VERSION = 3;
21	
22	/**
23	 * VERIFIED: evidence independent of the change shows it. REGRESSION_FREE: the tests pass, which shows only that nothing
24	 * they cover broke. UNVERIFIED: nothing was established (see `outcome` and `reason`). BLOCKED: a person must decide
25	 * before anything is run or concluded.
26	 */
27	export type VerifyVerdict = "VERIFIED" | "REGRESSION_FREE" | "UNVERIFIED" | "BLOCKED";
28	
29	/** Why the verdict is not VERIFIED: the outcome ladder's reasons, and the ones only `nexus verify` gives. */
30	export type VerifyReason =
31	  | EvidenceOutcomeReason
32	  /** Base and head are the same tree. */
33	  | "NOTHING_TO_VERIFY"
34	  /** The head changed the files that define the verifier, so the verifier was not run on the head. */
35	  | "VERIFIER_DEFINITION_CHANGED"
36	  /** The verifier is an inline program whose definition cannot be captured, so it was not run on the head. */
37	  | "VERIFIER_DEFINITION_NOT_CAPTURED"
38	  /** An enforced type-check failed on the head: an error in a changed file, or one the base did not have. */
39	  | "TYPECHECK_FAILED"
40	  /** An enforced type-check did not finish within the deadline. */
41	  | "TYPECHECK_TIMED_OUT"
42	  /** An enforced type-check could not be run: its tool is not installed, or its configuration is one this checker cannot run. */
43	  | "TYPECHECK_UNAVAILABLE"
44	  /** Type-checking is enforced and a project of the base tree has no counterpart in the head, so no evidence exists for it. */
45	  | "TYPECHECK_NOT_RUN"
46	  /** The change edits verification files (or weakens a test) and the edit was not approved, or the base's policy refuses such edits. */
47	  | "VERIFICATION_EDIT_BLOCKED"
48	  /** Not every changed file could be classified, so the guard's findings are not the whole picture. */
49	  | "GUARD_INCOMPLETE"
50	  /** A verifier discovered in the repository needs the operator's approval. */
51	  | "VERIFIER_NOT_APPROVED"
52	  /** Git was refused in the checkout (a planted or rewritten `.git`). */
53	  | "UNTRUSTED_CHECKOUT"
54	  /** A tree is larger than the limits, or reading it took longer than allowed. */
55	  | "TREE_LIMIT_EXCEEDED"
56	  /** A tree holds something that is not materialised (a submodule). */
57	  | "UNSUPPORTED_TREE"
58	  /** `--sandbox` was requested and the engine cannot confine a command here (or could not build the box for a run). */
59	  | "SANDBOX_UNAVAILABLE"
60	  /** The independent reviewer found a contradiction in the evidence, so the pass cannot be promoted to VERIFIED. */
61	  | "REVIEW_REJECTED"
62	  /** `nexus verify` itself failed; nothing was established. */
63	  | "INTERNAL_ERROR";
64	
65	export interface VerifyExitCode {
66	  code: number;
67	  name: string;
68	  when: string;
69	}
70	
71	/**
72	 * Every exit code of `nexus verify`, one row per condition (the same row shape as RUN_EXIT_CODES). A code can appear in
73	 * several rows: the exit code alone does not tell those conditions apart, the JSON document does. The "Exit codes"
74	 * table in docs/USER_MANUAL.md is this table. Unlike `nexus run`, code 3 exists (a person must decide) and an empty
75	 * change is not 0 (the caller chose the base).
76	 */
77	export const VERIFY_EXIT_CODES = [
78	  { code: 0, name: "verified", when: "`VERIFIED`: the change is shown by evidence independent of it." },
79	  { code: 1, name: "failed", when: "`UNVERIFIED` with outcome `NOT_ESTABLISHED`: the verifier failed or timed out on the head, an enforced type-check failed, timed out or could not be run, or the head changed the verifier's own definition so it was not run." },
80	  { code: 1, name: "error", when: "`UNVERIFIED` with reason `INTERNAL_ERROR`: `nexus verify` itself could not finish, so nothing was established." },
81	  { code: 1, name: "option_parse", when: "The command line could not be parsed: an unknown option or an option without its value (the option parser exits before the command runs; no JSON document)." },
82	  { code: 2, name: "unverified", when: "`REGRESSION_FREE` (the tests pass without showing the change), or `UNVERIFIED` because there is no verifier, no test executed, base and head are the same tree, or an enforced type-check project of the base has no counterpart in the head." },
83	  { code: 2, name: "usage", when: "A usage error: not a Git working tree, a base or head that does not name a commit, or an invalid option value or combination." },
84	  { code: 3, name: "blocked", when: "`BLOCKED`: a person must decide. The discovered verifier is not approved, the change edits verification files or weakens a test without approval, the changed files could not all be classified, the checkout is not trusted, a tree exceeds the limits or holds something that is not materialised (a submodule), or the default/selected sandbox engine is not usable, or the independent reviewer rejected contradictory evidence." },
85	  { code: 130, name: "interrupted", when: "Interrupted (SIGINT or SIGTERM). The signal is acted on when the running verifier process ends; a second signal exits at once and may leave no JSON document." },
86	] as const satisfies readonly VerifyExitCode[];
87	
88	export type VerifyExitName = (typeof VERIFY_EXIT_CODES)[number]["name"];
89	
90	export function verifyExitCode(name: VerifyExitName): number {
91	  return VERIFY_EXIT_CODES.find((row) => row.name === name)!.code;
92	}
93	
94	/** The verdict and exit-code row of every reason. A new reason does not compile until both are decided. */
95	export const VERIFY_REASONS: Record<VerifyReason, { verdict: Exclude<VerifyVerdict, "VERIFIED">; exit: VerifyExitName }> = {
96	  REGRESSION_FREE: { verdict: "REGRESSION_FREE", exit: "unverified" },
97	  NO_APPLICABLE_VERIFIER: { verdict: "UNVERIFIED", exit: "unverified" },
98	  NO_TESTS_EXECUTED: { verdict: "UNVERIFIED", exit: "unverified" },
99	  VERIFICATION_NOT_RUN: { verdict: "UNVERIFIED", exit: "unverified" },
100	  NOTHING_TO_VERIFY: { verdict: "UNVERIFIED", exit: "unverified" },
101	  TYPECHECK_NOT_RUN: { verdict: "UNVERIFIED", exit: "unverified" },
102	  TYPECHECK_FAILED: { verdict: "UNVERIFIED", exit: "failed" },
103	  TYPECHECK_TIMED_OUT: { verdict: "UNVERIFIED", exit: "failed" },
104	  TYPECHECK_UNAVAILABLE: { verdict: "UNVERIFIED", exit: "failed" },
105	  VERIFIER_FAILED: { verdict: "UNVERIFIED", exit: "failed" },
106	  VERIFIER_TIMED_OUT: { verdict: "UNVERIFIED", exit: "failed" },
107	  VERIFIER_DEFINITION_CHANGED: { verdict: "UNVERIFIED", exit: "failed" },
108	  VERIFIER_DEFINITION_NOT_CAPTURED: { verdict: "UNVERIFIED", exit: "failed" },
109	  INTERNAL_ERROR: { verdict: "UNVERIFIED", exit: "error" },
110	  VERIFIER_NOT_APPROVED: { verdict: "BLOCKED", exit: "blocked" },
111	  VERIFICATION_EDIT_BLOCKED: { verdict: "BLOCKED", exit: "blocked" },
112	  GUARD_INCOMPLETE: { verdict: "BLOCKED", exit: "blocked" },
113	  UNTRUSTED_CHECKOUT: { verdict: "BLOCKED", exit: "blocked" },
114	  TREE_LIMIT_EXCEEDED: { verdict: "BLOCKED", exit: "blocked" },
115	  UNSUPPORTED_TREE: { verdict: "BLOCKED", exit: "blocked" },
116	  SANDBOX_UNAVAILABLE: { verdict: "BLOCKED", exit: "blocked" },
117	  REVIEW_REJECTED: { verdict: "BLOCKED", exit: "blocked" },
118	};
119	
120	/** The verdict for a reason; no reason is VERIFIED. */
121	export function verifyVerdictFor(reason: VerifyReason | undefined): VerifyVerdict {
122	  return reason === undefined ? "VERIFIED" : VERIFY_REASONS[reason].verdict;
123	}
124	
125	/** The exit-code row for a reason; no reason is VERIFIED. */
126	export function verifyExitNameFor(reason: VerifyReason | undefined): VerifyExitName {
127	  return reason === undefined ? "verified" : VERIFY_REASONS[reason].exit;
128	}
129	
130	/** One side of the comparison. */
131	export interface VerifyTreeRef {
132	  /** What the operator named: a ref, or "(working tree)". */
133	  ref: string;
134	  /** The commit; null for the working tree, which has none. */
135	  commit: string | null;
136	  /** The Git tree that was materialised and verified. For the working tree: tracked and untracked files that are not ignored, as `git add -A` would stage them (Nexus's own `.nexus` state left out). */
137	  tree: string;
138	  workingTree: boolean;
139	}
140	
141	export interface VerifyVerifierRecord {
142	  command: string;
143	  /** `configured`: the operator's `--verifier`. `discovered`: selected from the files of the base tree. */
144	  source: "configured" | "discovered";
145	  /** The base-tree file that justifies a discovered verifier, or "configured". */
146	  evidence: string;
147	  /** sha256 of the command and the script body it resolves to in the base tree. */
148	  digest: string;
149	  /** How it was approved: it is the operator's own command, `--yes`, a matching `--approve-verifier` digest, or not at all. */
150	  approval: "operator_command" | "yes" | "digest" | "none";
151	  /** The script body the command resolves to in the base tree (capped), when there is one. */
152	  script?: string;
153	}
154	
155	/** A sandbox engine `--sandbox` can name: Bubblewrap or Docker (the ones `nexus run --sandbox` uses). */
156	export type VerifySandboxEngine = "bwrap" | "docker";
157	
158	/**
159	 * How the processes `nexus verify` started on repository content were confined: the verifier on each side, the base's
160	 * tests against the head, and the type-checks. One answer for all of them: a run is never started outside a sandbox
161	 * that was requested.
162	 */
163	export interface VerifySandbox {
164	  /** The operator explicitly selected a sandbox; the effective engine and run records also show default confinement. */
165	  requested: boolean;
166	  /** The engine every process ran in. `none`: no sandbox (not requested, or requested and unavailable, in which case nothing ran). */
167	  engine: VerifySandboxEngine | "none";
168	  /** The confined processes could use the network (`--sandbox-network`). Always false when `engine` is `none`: an unconfined process has the caller's network, which this member does not describe. */
169	  network: boolean;
170	}
171	
172	export interface VerifyRunRecord {
173	  /** `base_tests_on_head`: the test files as they were on the base, run against the head's code. */
174	  phase: "base" | "head" | "base_tests_on_head";
175	  /** The process ran inside the sandbox named in `sandbox.engine`. Always written; absent only in a document from before `--sandbox` existed (the run was not sandboxed). */
176	  sandboxed?: boolean;
177	  /** Test-oracle files or candidate-only workspace paths opened/observed more often than by the base run. Such a pass is not independent; paths can include test-support data, not only test files. */
178	  testFixtureReads?: string[];
179	  passed: boolean;
180	  timedOut: boolean;
181	  /** Null when the process was killed or never started. */
182	  exitCode: number | null;
183	  /** The output shows at least one test that ran. */
184	  executedTests: boolean;
185	  outputSha256: string;
186	  outputTruncated: boolean;
187	  durationMs: number;
188	  /** The end of the output of a run that did not pass: repository-controlled text, redacted and capped. */
189	  outputTail?: string;
190	}
191	
192	export interface VerifyBaselineSummary {
193	  /** The verifier failed on the base tree. */
194	  failed: boolean;
195	  /** The base run can serve as the "failed before" half: it failed, by itself, with tests that ran. */
196	  usable: boolean;
197	  /** Test files captured from the base tree; null when one was too large to capture. */
198	  testFiles: number | null;
199	  /** The files that define the verifier were captured from the base tree. */
200	  verifierDefinitionBound: boolean;
201	  /** Why they could not be captured. */
202	  verifierUnbindableReason?: string;
203	}
204	
205	/** An ingredient of the verdict that this version does not run. Later versions add statuses and members. */
206	export interface VerifyIngredient {
207	  status: "NOT_RUN";
208	  detail?: string;
209	}
210	
211	/**
212	 * The independent reviewer's result. `NOT_RUN` is honest when no head verifier ran, so nothing was reviewed;
213	 * `COMPLETE` publishes only the members this reviewer writes, using the vocabulary of the project's existing
214	 * `IndependentReviewVerdict` (ACCEPT/REJECT, observations, defects, unproven criteria and scope violations). Internal
215	 * members such as `boundaryReport`, `changeAssessment` and a defect's optional line are deliberately not published.
216	 * A REJECT can withhold VERIFIED but never raise a verdict: deterministic verifier evidence stays the authority for a
217	 * passing result.
218	 */
219	export type VerifyReview =
220	  | VerifyIngredient
221	  | {
222	      status: "COMPLETE";
223	      detail?: string;
224	      verdict: "ACCEPT" | "REJECT";
225	      verifiedObservations: string[];
226	      suspectedDefects: Array<{ path: string; description: string }>;
227	      unprovenCriteria: string[];
228	      scopeViolations: string[];
229	      reviewerConfidenceNote: string;
230	    };
231	
232	/**
233	 * The project type-checks. The evidence of every project (tool, configuration, status, counts, tool hash) is in
234	 * `verification.typecheck.projects`; this is the summary and the base side.
235	 */
236	export interface VerifyTypecheck {
237	  /**
238	   * NOT_RUN: the verifier did not pass on the head (or verification stopped earlier), so no type-check was run.
239	   * Otherwise the combined status of the head's projects, as in `verification.typecheck.status`.
240	   */
241	  status: "NOT_RUN" | TypecheckEvidence["status"];
242	  /** `enforce`: a failing check lowers the verdict. `record`: recorded only (your own `--verifier`). `off`: disabled by NEXUS_TYPECHECK. */
243	  mode?: TypecheckMode;
244	  detail?: string;
245	  /** The same projects on the base tree: what a "new" error on the head is measured against. */
246	  baseline?: TypecheckBaselineRecord[];
247	  /** Projects of the base tree that the head no longer has (tool and configuration path). */
248	  missingFromHead?: string[];
249	}
250	
251	/** One changed file that decides how the change is verified. */
252	export interface VerifyGuardFinding {
253	  path: string;
254	  class: VerificationClass;
255	  kind: "added" | "modified" | "deleted";
256	  /** For a test file: what the edit removed (a heuristic over the text). Absent when nothing was detected. */
257	  weakening?: string[];
258	  /** The edit needs `--approve-verification-edit <path>`: a verification configuration file, or a weakened test. */
259	  requiresApproval: boolean;
260	  /** The operator approved this path. Approval lets the verdict be reported; it never makes the change VERIFIED. */
261	  approved: boolean;
262	}
263	
264	/** The verification-file guard: which changed files define or weaken the verification, under the BASE tree's policy. */
265	export interface VerifyGuard {
266	  /** NOT_RUN: verification stopped before the change was read. CLEAR: nothing waits for a decision. BLOCKED: a finding does, or the scan is incomplete. */
267	  status: "NOT_RUN" | "CLEAR" | "BLOCKED";
268	  /** `approve`: a finding that requires approval blocks until approved. `block`: it blocks, and approval is not accepted. */
269	  mode?: VerificationMode;
270	  /** `base_tree`: the base tree's `.nexus-security.json` (it can only tighten). `default`: the base tree has none. The head's is never read. */
271	  policySource?: "base_tree" | "default";
272	  findings: VerifyGuardFinding[];
273	  /** False when a changed file could not be classified (unreadable, too large, or too many findings). */
274	  complete: boolean;
275	  detail?: string;
276	}
277	
278	export interface VerifyLimits {
279	  /** Deadline of each verifier run, and of the type-checks of each side, in seconds. */
280	  timeoutSecs: number;
281	  maxTreeFiles: number;
282	  maxTreeBytes: number;
283	}
284	
285	/** Printed when verification reached a verdict, whatever the verdict. It is also the receipt. */
286	export interface VerifyJsonResult {
287	  /** Version of this document's schema. Always the first member. */
288	  schema_version: typeof VERIFY_RESULT_SCHEMA_VERSION;
289	  verdict: VerifyVerdict;
290	  outcome: Exclude<EngineeringOutcome, "NOT_REQUIRED">;
291	  /** Absent only when the verdict is VERIFIED. */
292	  reason?: VerifyReason;
293	  detail?: string;
294	  /** The process exit code. */
295	  exitCode: number;
296	  /** Absent when the checkout was refused before anything was resolved. */
297	  base?: VerifyTreeRef;
298	  head?: VerifyTreeRef;
299	  /** Paths that differ between base and head (at most 200 are listed). */
300	  changedFiles: string[];
301	  changedFileCount: number;
302	  /** Absent when no verifier applies. */
303	  verifier?: VerifyVerifierRecord;
304	  /** The operator-declared deliverable files. */
305	  deliverables: string[];
306	  /** The paths given with `--approve-verification-edit`. */
307	  approvedVerificationEdits: string[];
308	  /** Every verifier process that ran, in order. */
309	  runs: VerifyRunRecord[];
310	  baseline?: VerifyBaselineSummary;
311	  /** The evidence the outcome was derived from. */
312	  verification?: VerificationEvidence;
313	  typecheck: VerifyTypecheck;
314	  guard: VerifyGuard;
315	  review: VerifyReview;
316	  /** Always written; absent only in a document from before `--sandbox` existed (nothing was sandboxed). */
317	  sandbox?: VerifySandbox;
318	  /** Sandbox refusals encountered in this run. Present only when one happened; a denial is evidence, never an approval. */
319	  sandboxEvents?: SandboxDenialEvent[];
320	  /** Dependency directories of the caller's checkout that were linked into both scratch trees. */
321	  linkedDependencyDirs: string[];
322	  limits: VerifyLimits;
323	  /** Names (never values) of verdict-affecting environment variables that were set. */
324	  environment: string[];
325	  nexusVersion: string;
326	  startedAt: string;
327	  durationMs: number;
328	}
329	
330	/** Printed instead of a result when no verdict was reached: a usage error or an interruption. */
331	export interface VerifyJsonError {
332	  /** Version of this document's schema. Always the first member. */
333	  schema_version: typeof VERIFY_RESULT_SCHEMA_VERSION;
334	  error: string;
335	  /** The process exit code. */
336	  exitCode: number;
337	}
338	
339	/** The one JSON document `nexus verify --json` writes to stdout. A result has `verdict`; an error document does not. */
340	export type VerifyJsonOutput = VerifyJsonResult | VerifyJsonError;
341

