1	/** ACP v1 stdio transport and runtime adapter for Nexus's existing sidecar protocol. */
2	import * as fs from "node:fs";
3	import * as path from "node:path";
4	import type { HarnessConfig } from "./types.js";
5	import { ApplicationCore } from "./core/app.js";
6	import { formatSafeSidecarDiagnostic, SidecarServer } from "./sidecar.js";
7	import { PROTOCOL_VERSION, SIDECAR_MAX_HISTORY_PAGES, type SidecarEvent } from "./protocol.js";
8	import {
9	  ACP_CANCEL_REQUEST_METHOD, ACP_ERROR, ACP_MAX_INFLIGHT_REQUESTS, ACP_MAX_PENDING_PERMISSIONS_PER_SESSION,
10	  ACP_MAX_OVERSIZED_LINES, ACP_MAX_SESSIONS, ACP_PERMISSION_TIMEOUT_SECS, ACP_RECEIPT_STORE_SIZE, ACP_TOMBSTONE_COUNT,
11	  type AcpId, type AcpVerification,
12	} from "./acp/types.js";
13	import {
14	  BoundedLineReader, RequestCorrelator, encodeMessage, errorResponse, notification,
15	  oversizedLineError, parseMessage, request, resultResponse,
16	} from "./acp/jsonrpc.js";
17	import {
18	  approvalToPermissionRequest, assistantDeltaToUpdate, bindApprovalToToolCall, cancelledRequestError,
19	  fileDiffToUpdate, historyToReplay, initializeResult, loadSessionResult, newSessionResult, nexusReceipt,
20	  permissionReplyToCommand, promptResult, sessionUpdate, sidecarErrorToRpc, toolEndToUpdate, toolStartToUpdate,
21	  turnToStop, verificationFromTurn, verificationUpdate, verdictChunk,
22	} from "./acp/mapping.js";
23	import {
24	  canonicalCwd, validateCancel, validateCancelRequest, validateInitialize, validateLoadSession,
25	  validateNewSession, validatePrompt, validateReceiptGet,
26	} from "./acp/validate.js";
27	
28	type SidecarLike = { start(): void; handleLine(line: string): Promise<void> };
29	type Session = {
30	  id: string; cwd: string; mcp: { count: number; names: string[] }; sidecar: SidecarLike;
31	  events: SidecarEvent[]; tools: SidecarEvent[]; pendingPrompt?: { rpcId: AcpId; commandId: string };
32	  pendingApproval?: { id: string; rpcId: number; toolCallId: string; timer: NodeJS.Timeout };
33	  pendingReceipt?: { commandId: string; resolve: (event: SidecarEvent | undefined) => void };
34	  /** The prompt was answered early (cancelled request, refused checkpoint) and its turn is still winding down: no new prompt until the turn's result arrives, or that result would answer the new prompt. */
35	  stopping?: boolean;
36	};
37	
38	export interface AcpStdioOptions {
39	  config: HarnessConfig;
40	  version: string;
41	  write?: (line: string) => void;
42	  createSidecar?: (config: HarnessConfig, resume: string | undefined, write: (line: string) => void) => SidecarLike;
43	  realpath?: (value: string) => string;
44	  isDirectory?: (value: string) => boolean;
45	  /** How long a signalled process waits for its sessions to stop before it exits anyway. */
46	  shutdownGraceMs?: number;
47	}
48	
49	const ACP_SHUTDOWN_GRACE_MS = 10_000;
50	
51	/** One ACP connection. Every session still executes through ApplicationCore and SidecarServer gates. */
52	export class AcpStdioServer {
53	  private readonly write: (line: string) => void;
54	  private readonly reader = new BoundedLineReader();
55	  private readonly permissionRequests = new RequestCorrelator<{ sessionId: string; approvalId: string }>({ tombstones: ACP_TOMBSTONE_COUNT });
56	  private readonly sessions = new Map<string, Session>();
57	  private readonly receipts = new Map<string, ReturnType<typeof nexusReceipt>>();
58	  private readonly pending = new Map<string, AcpId>();
59	  private readonly loadingSessionIds = new Set<string>();
60	  private startingSessions = 0;
61	  private initialized = false;
62	  private closed = false;
63	
64	  constructor(private readonly options: AcpStdioOptions) {
65	    this.write = options.write ?? ((line) => process.stdout.write(line));
66	  }
67	
68	  /** Feed raw stdin bytes. Invalid/oversized lines are answered without retaining unbounded input. */
69	  push(chunk: Uint8Array): void {
70	    if (this.closed) return;
71	    for (const event of this.reader.push(chunk)) {
72	      if (this.closed) break;
73	      if (event.kind === "oversized") {
74	        this.write(encodeMessage(oversizedLineError()));
75	        if (this.reader.oversizedLines >= ACP_MAX_OVERSIZED_LINES) void this.close();
76	      }
77	      else void this.receive(event.text);
78	    }
79	  }
80	
81	  async close(): Promise<void> {
82	    this.closed = true;
83	    const shutdowns: Promise<void>[] = [];
84	    for (const session of this.sessions.values()) {
85	      if (session.pendingApproval) clearTimeout(session.pendingApproval.timer);
86	      shutdowns.push(session.sidecar.handleLine(JSON.stringify({ v: PROTOCOL_VERSION, type: "shutdown" })));
87	    }
88	    this.sessions.clear();
89	    this.pending.clear();
90	    await Promise.allSettled(shutdowns);
91	  }
92	
93	  private send(message: object): void {
94	    if (!this.closed) this.write(encodeMessage(message));
95	  }
96	
97	  private requestKey(id: AcpId): string { return `${typeof id}:${String(id)}`; }
98	
99	  private async receive(line: string): Promise<void> {
100	    const incoming = parseMessage(line);
101	    if (incoming.kind === "invalid") {
102	      if (incoming.respond) this.send(errorResponse(incoming.id, incoming.error));
103	      return;
104	    }
105	    if (incoming.kind === "response") {
106	      const settled = this.permissionRequests.settle(incoming.id);
107	      if (settled.state !== "matched") return;
108	      const session = this.sessions.get(settled.context.sessionId);
109	      if (!session?.pendingApproval || session.pendingApproval.rpcId !== incoming.id) return;
110	      const pending = session.pendingApproval;
111	      clearTimeout(pending.timer);
112	      session.pendingApproval = undefined;
113	      const command = permissionReplyToCommand(pending.id, incoming);
114	      await this.sidecarCommand(session, command.type === "approve"
115	        ? { type: "approve", id: command.id, always: false }
116	        : { type: "deny", id: command.id });
117	      return;
118	    }
119	    if (this.pending.size >= ACP_MAX_INFLIGHT_REQUESTS && incoming.kind === "request") {
120	      this.send(errorResponse(incoming.id, { code: ACP_ERROR.INTERNAL_ERROR, message: "too many requests are in flight" }));
121	      return;
122	    }
123	    if (incoming.kind === "request") this.pending.set(this.requestKey(incoming.id), incoming.id);
124	    try {
125	      await this.dispatch(incoming);
126	    } catch (err) {
127	      if (incoming.kind === "request") this.replyError(incoming.id, { code: ACP_ERROR.INTERNAL_ERROR, message: formatSafeSidecarDiagnostic([err]) });
128	    } finally {
129	      const promptStillRunning = incoming.kind === "request" && incoming.method === "session/prompt"
130	        && [...this.sessions.values()].some((session) => session.pendingPrompt?.rpcId === incoming.id);
131	      if (incoming.kind === "request" && !promptStillRunning) this.pending.delete(this.requestKey(incoming.id));
132	    }
133	  }
134	
135	  private replyError(id: AcpId, error: { code: number; message: string; data?: unknown }): void {
136	    this.send(errorResponse(id, error as any));
137	  }
138	
139	  private async dispatch(message: Exclude<ReturnType<typeof parseMessage>, { kind: "invalid" | "response" }>): Promise<void> {
140	    if (message.kind === "request" && !this.initialized && message.method !== "initialize") {
141	      this.replyError(message.id, { code: ACP_ERROR.INVALID_REQUEST, message: "initialize must be the first request" });
142	      return;
143	    }
144	    if (message.method === "initialize" && message.kind === "request") {
145	      if (this.initialized) { this.replyError(message.id, { code: ACP_ERROR.INVALID_REQUEST, message: "initialize was already completed" }); return; }
146	      const parsed = validateInitialize(message.params);
147	      if (!parsed.ok) { this.replyError(message.id, parsed.error); return; }
148	      this.initialized = true;
149	      this.send(resultResponse(message.id, initializeResult({ version: this.options.version, sidecarProtocol: PROTOCOL_VERSION })));
150	      return;
151	    }
152	    if (!this.initialized) return;
153	    if (message.method === "session/new" && message.kind === "request") return this.newSession(message.id, message.params);
154	    if (message.method === "session/load" && message.kind === "request") return this.loadSession(message.id, message.params);
155	    if (message.method === "session/prompt" && message.kind === "request") return this.prompt(message.id, message.params);
156	    if (message.method === "session/cancel" && message.kind === "notification") {
157	      const parsed = validateCancel(message.params);
158	      if (parsed.ok) { const session = this.sessions.get(parsed.value.sessionId); if (session) await this.sidecarCommand(session, { type: "cancel" }); }
159	      return;
160	    }
161	    if (message.method === ACP_CANCEL_REQUEST_METHOD && message.kind === "notification") {
162	      const parsed = validateCancelRequest(message.params);
163	      if (parsed.ok) {
164	        const approval = this.permissionRequests.abandon(parsed.value.requestId as number);
165	        if (approval) {
166	          const session = this.sessions.get(approval.sessionId);
167	          if (session?.pendingApproval?.rpcId === parsed.value.requestId) {
168	            clearTimeout(session.pendingApproval.timer);
169	            const approvalId = session.pendingApproval.id;
170	            session.pendingApproval = undefined;
171	            await this.sidecarCommand(session, { type: "deny", id: approvalId });
172	          }
173	        }
174	        const id = this.pending.get(this.requestKey(parsed.value.requestId));
175	        if (id !== undefined) {
176	          for (const session of this.sessions.values()) if (session.pendingPrompt?.rpcId === id) {
177	            session.pendingPrompt = undefined;
178	            session.stopping = true;
179	            // The permission the cancelled prompt was waiting on dies with it; left in place it would silently deny
180	            // the next prompt's first approval.
181	            await this.dropPendingApproval(session, true);
182	            await this.sidecarCommand(session, { type: "cancel" });
183	            this.send(cancelledRequestError(id));
184	            this.pending.delete(this.requestKey(id));
185	          }
186	        }
187	      }
188	      return;
189	    }
190	    if (message.method === "_nexus/receipt/get" && message.kind === "request") return this.getReceipt(message.id, message.params);
191	    if (message.kind === "request") this.replyError(message.id, { code: ACP_ERROR.METHOD_NOT_FOUND, message: `method not found: ${message.method}` });
192	  }
193	
194	  private canonical(cwd: string): string | undefined {
195	    const result = canonicalCwd(cwd, {
196	      realpath: this.options.realpath ?? ((value) => fs.realpathSync(value)),
197	      isDirectory: this.options.isDirectory ?? ((value) => fs.statSync(value).isDirectory()),
198	    });
199	    return result.ok ? result.value : undefined;
200	  }
201	
202	  private async startSession(cwd: string, mcp: { count: number; names: string[] }, resume?: string): Promise<Session | undefined> {
203	    const config = { ...this.options.config, workspace: cwd, surface: "tui" as const };
204	    const events: SidecarEvent[] = [];
205	    const early: string[] = [];
206	    let session: Session;
207	    const sink = (line: string) => session ? this.onSidecarLine(session, line) : early.push(line);
208	    const sidecar = this.options.createSidecar?.(config, resume, sink)
209	      ?? new SidecarServer({ app: new ApplicationCore(config), resume, fullHistoryReplay: resume !== undefined, write: sink });
210	    session = { id: "", cwd, mcp, sidecar, events, tools: [] };
211	    try {
212	      sidecar.start();
213	    } catch (err) {
214	      await sidecar.handleLine(JSON.stringify({ v: PROTOCOL_VERSION, type: "shutdown" }));
215	      throw err;
216	    }
217	    for (const line of early) this.onSidecarLine(session, line);
218	    await new Promise((resolve) => setImmediate(resolve));
219	    if (this.closed) {
220	      await sidecar.handleLine(JSON.stringify({ v: PROTOCOL_VERSION, type: "shutdown" }));
221	      return undefined;
222	    }
223	    const state = events.find((event) => event.type === "session.state") as Extract<SidecarEvent, { type: "session.state" }> | undefined;
224	    if (!state?.session || (resume !== undefined && state.session !== resume)) {
225	      await sidecar.handleLine(JSON.stringify({ v: PROTOCOL_VERSION, type: "shutdown" }));
226	      return undefined;
227	    }
228	    session.id = state.session;
229	    return session;
230	  }
231	
232	  private async newSession(id: AcpId, params: unknown): Promise<void> {
233	    const parsed = validateNewSession(params);
234	    if (!parsed.ok) { this.replyError(id, parsed.error); return; }
235	    const cwd = this.canonical(parsed.value.cwd);
236	    if (!cwd) { this.replyError(id, { code: ACP_ERROR.INVALID_PARAMS, message: "cwd does not exist or is not a readable directory" }); return; }
237	    if (this.sessions.size + this.startingSessions >= ACP_MAX_SESSIONS) { this.replyError(id, { code: ACP_ERROR.INTERNAL_ERROR, message: "the connection already has the maximum number of sessions" }); return; }
238	    this.startingSessions++;
239	    try {
240	      const session = await this.startSession(cwd, parsed.value.mcpServers);
241	      if (!session) { if (!this.closed) this.replyError(id, { code: ACP_ERROR.INTERNAL_ERROR, message: "sidecar did not establish a session" }); return; }
242	      if (this.sessions.has(session.id)) { await session.sidecar.handleLine(JSON.stringify({ v: PROTOCOL_VERSION, type: "shutdown" })); this.replyError(id, { code: ACP_ERROR.INTERNAL_ERROR, message: "the sidecar generated a duplicate session id" }); return; }
243	      this.sessions.set(session.id, session);
244	      const state = session.events.find((event) => event.type === "session.state") as any;
245	      this.send(resultResponse(id, newSessionResult(state, session.mcp) ?? { sessionId: session.id }));
246	    } finally {
247	      this.startingSessions--;
248	    }
249	  }
250	
251	  private async loadSession(id: AcpId, params: unknown): Promise<void> {
252	    const parsed = validateLoadSession(params);
253	    if (!parsed.ok) { this.replyError(id, parsed.error); return; }
254	    const cwd = this.canonical(parsed.value.cwd);
255	    if (!cwd) { this.replyError(id, { code: ACP_ERROR.INVALID_PARAMS, message: "cwd does not exist or is not a readable directory" }); return; }
256	    if (this.sessions.has(parsed.value.sessionId) || this.loadingSessionIds.has(parsed.value.sessionId)) { this.replyError(id, { code: ACP_ERROR.INVALID_PARAMS, message: "session is already active on this connection" }); return; }
257	    if (this.sessions.size + this.startingSessions >= ACP_MAX_SESSIONS) { this.replyError(id, { code: ACP_ERROR.INTERNAL_ERROR, message: "the connection already has the maximum number of sessions" }); return; }
258	    this.startingSessions++;
259	    this.loadingSessionIds.add(parsed.value.sessionId);
260	    try {
261	      const session = await this.startSession(cwd, parsed.value.mcpServers, parsed.value.sessionId);
262	      if (!session) { if (!this.closed) this.replyError(id, { code: ACP_ERROR.INTERNAL_ERROR, message: "session could not be loaded" }); return; }
263	      const pages = session.events.filter((event): event is Extract<SidecarEvent, { type: "history" }> => event.type === "history");
264	      const first = pages[0];
265	      const valid = Boolean(first && !first.error && Number.isSafeInteger(first.total) && first.total >= 0 &&
266	        Number.isSafeInteger(first.pages) && first.pages! > 0 && first.pages! <= SIDECAR_MAX_HISTORY_PAGES &&
267	        pages.length === first.pages && pages.every((page, index) => !page.error && page.session === session.id &&
268	          page.total === first.total && page.pages === first.pages && page.page === index && Array.isArray(page.messages) &&
269	          page.messages.every((entry: unknown) => {
270	            if (!entry || typeof entry !== "object") return false;
271	            const value = entry as Record<string, unknown>;
272	            if (typeof value.text !== "string") return false;
273	            if (["user", "steering", "assistant"].includes(String(value.role))) return true;
274	            if (value.role === "tool") return (value.tool === undefined || typeof value.tool === "string") &&
275	              (value.toolCallId === undefined || typeof value.toolCallId === "string") &&
276	              (value.status === undefined || ["pending", "completed", "failed"].includes(String(value.status)));
277	            if (value.role === "tool_result") return typeof value.toolCallId === "string" &&
278	              (value.status === undefined || ["completed", "failed"].includes(String(value.status)));
279	            return value.role === "outcome" && (value.heading === undefined || typeof value.heading === "string") &&
280	              (value.text === undefined || typeof value.text === "string");
281	          })));
282	      if (!valid || !first) {
283	        await session.sidecar.handleLine(JSON.stringify({ v: PROTOCOL_VERSION, type: "shutdown" }));
284	        this.replyError(id, { code: ACP_ERROR.INTERNAL_ERROR, message: first?.error ?? "session history is incomplete or invalid; no history was replayed" });
285	        return;
286	      }
287	      const replay = pages.map((page) => historyToReplay(page));
288	      const extent = { sent: replay.reduce((sum, page) => sum + page.extent.sent, 0), total: first.total };
289	      if (!Number.isSafeInteger(extent.total) || extent.total < 0 || extent.sent !== extent.total) {
290	        await session.sidecar.handleLine(JSON.stringify({ v: PROTOCOL_VERSION, type: "shutdown" }));
291	        this.replyError(id, { code: ACP_ERROR.INTERNAL_ERROR, message: "session history is incomplete; no history was replayed" });
292	        return;
293	      }
294	      for (const page of replay) for (const update of page.updates) this.send(sessionUpdate(session.id, update));
295	      this.sessions.set(session.id, session);
296	      const state = session.events.find((event) => event.type === "session.state") as any;
297	      this.send(resultResponse(id, loadSessionResult(state, session.mcp, extent)));
298	    } finally {
299	      this.startingSessions--;
300	      this.loadingSessionIds.delete(parsed.value.sessionId);
301	    }
302	  }
303	
304	  private async prompt(id: AcpId, params: unknown): Promise<void> {
305	    const rawSessionId = (params && typeof params === "object") ? (params as any).sessionId : undefined;
306	    const session = typeof rawSessionId === "string" ? this.sessions.get(rawSessionId) : undefined;
307	    if (!session) { this.replyError(id, { code: ACP_ERROR.INVALID_PARAMS, message: "sessionId is not active on this connection" }); return; }
308	    const parsed = validatePrompt(params, { workspace: session.cwd, fs: { realpath: (value) => fs.realpathSync(value), isDirectory: (value) => fs.statSync(value).isDirectory() } });
309	    if (!parsed.ok) { this.replyError(id, parsed.error); return; }
310	    if (session.pendingPrompt) { this.replyError(id, { code: ACP_ERROR.INTERNAL_ERROR, message: "this session already has a prompt in progress" }); return; }
311	    if (session.stopping) { this.replyError(id, { code: ACP_ERROR.INTERNAL_ERROR, message: "the previous prompt of this session is still stopping; send the prompt again" }); return; }
312	    const commandId = `acp-${String(id).slice(0, 180)}`;
313	    session.pendingPrompt = { rpcId: id, commandId };
314	    await this.sidecarCommand(session, { type: "prompt.submit", id: commandId, text: parsed.value.text });
315	  }
316	
317	  private async getReceipt(id: AcpId, params: unknown): Promise<void> {
318	    const parsed = validateReceiptGet(params);
319	    if (!parsed.ok) { this.replyError(id, parsed.error); return; }
320	    const receipt = parsed.value.receiptId ? this.receipts.get(parsed.value.receiptId) : [...this.receipts.values()].reverse().find((value) => value.session_id === parsed.value.sessionId);
321	    if (!receipt || receipt.session_id !== parsed.value.sessionId) { this.replyError(id, { code: ACP_ERROR.INVALID_PARAMS, message: "receipt is not available on this connection" }); return; }
322	    this.send(resultResponse(id, receipt));
323	  }
324	
325	  private async sidecarCommand(session: Session, command: Record<string, unknown>): Promise<void> {
326	    await session.sidecar.handleLine(JSON.stringify({ v: PROTOCOL_VERSION, ...command }));
327	  }
328	
329	  private onSidecarLine(session: Session | undefined, line: string): void {
330	    if (!session) return;
331	    let event: SidecarEvent;
332	    try { event = JSON.parse(line); } catch { return; }
333	    session.events.push(event);
334	    if (session.events.length > 2_000) session.events.shift();
335	    if (event.type === "tool.start") {
336	      session.tools.push(event);
337	      this.send(sessionUpdate(session.id, toolStartToUpdate(event as any)));
338	    } else if (event.type === "assistant.delta") this.send(sessionUpdate(session.id, assistantDeltaToUpdate(event as any)));
339	    else if (event.type === "file.diff") this.send(sessionUpdate(session.id, fileDiffToUpdate(event as any, session.cwd)));
340	    else if (event.type === "tool.end") this.send(sessionUpdate(session.id, toolEndToUpdate(event as any)));
341	    else if (event.type === "approval.request") this.permission(session, event as any);
342	    else if (event.type === "checkpoint.choice.request") this.checkpointChoice(session, event);
343	    else if (event.type === "turn.result") void this.finishPrompt(session, event as any);
344	    else if (event.type === "error" && session.pendingPrompt && event.id === session.pendingPrompt.commandId) {
345	      this.replyError(session.pendingPrompt.rpcId, sidecarErrorToRpc(event as any));
346	      this.pending.delete(this.requestKey(session.pendingPrompt.rpcId));
347	      session.pendingPrompt = undefined;
348	    }
349	    if (session.pendingReceipt && event.type === "receipt" && event.id === session.pendingReceipt.commandId) {
350	      const pending = session.pendingReceipt; session.pendingReceipt = undefined; pending.resolve(event);
351	    }
352	    if (event.type === "session.state") {
353	      if (!session.id && event.session) session.id = event.session;
354	      // A pre-turn refusal (for example a cancelled checkpoint choice or provider-gate cancellation) ends with a
355	      // terminal `error`, not `turn.result`. Keep the session blocked until Sidecar confirms its job is idle.
356	      if (session.stopping && event.busy === false) session.stopping = false;
357	    }
358	  }
359	
360	  /** Forget the session's open permission request: stop its timer, stop accepting a reply, and (optionally) deny it. */
361	  private async dropPendingApproval(session: Session, deny: boolean): Promise<void> {
362	    const approval = session.pendingApproval;
363	    if (!approval) return;
364	    clearTimeout(approval.timer);
365	    this.permissionRequests.abandon(approval.rpcId);
366	    session.pendingApproval = undefined;
367	    if (deny) await this.sidecarCommand(session, { type: "deny", id: approval.id });
368	  }
369	
370	  /**
371	   * A checkpoint that cannot be made asks the operator how to go on. No ACP client may answer that, and the adapter
372	   * never picks read-only, no-checkpoint or allow-sensitive for the operator: it cancels, and the prompt fails with
373	   * the sidecar's message.
374	   */
375	  private checkpointChoice(session: Session, event: Extract<SidecarEvent, { type: "checkpoint.choice.request" }>): void {
376	    const prompt = session.pendingPrompt;
377	    if (prompt) {
378	      session.pendingPrompt = undefined;
379	      session.stopping = true;
380	      this.replyError(prompt.rpcId, { code: ACP_ERROR.INTERNAL_ERROR, message: formatSafeSidecarDiagnostic([event.message]) });
381	      this.pending.delete(this.requestKey(prompt.rpcId));
382	    }
383	    void this.sidecarCommand(session, { type: "checkpoint.choice", id: event.id, choice: "cancel" });
384	  }
385	
386	  private permission(session: Session, event: Extract<SidecarEvent, { type: "approval.request" }>): void {
387	    if (session.pendingApproval || ACP_MAX_PENDING_PERMISSIONS_PER_SESSION !== 1) {
388	      void this.sidecarCommand(session, { type: "deny", id: event.id }); return;
389	    }
390	    const toolCallId = bindApprovalToToolCall(event as any, session.tools as any);
391	    const rpcId = this.permissionRequests.open({ sessionId: session.id, approvalId: event.id });
392	    const timer = setTimeout(() => {
393	      this.permissionRequests.abandon(rpcId);
394	      if (session.pendingApproval?.rpcId === rpcId) session.pendingApproval = undefined;
395	      void this.sidecarCommand(session, { type: "deny", id: event.id });
396	    }, ACP_PERMISSION_TIMEOUT_SECS * 1000);
397	    timer.unref?.();
398	    session.pendingApproval = { id: event.id, rpcId, toolCallId, timer };
399	    this.send(approvalToPermissionRequest(event as any, { rpcId, sessionId: session.id, toolCallId, workspace: session.cwd }));
400	  }
401	
402	  private async finishPrompt(session: Session, event: Extract<SidecarEvent, { type: "turn.result" }>): Promise<void> {
403	    const pending = session.pendingPrompt;
404	    // The turn is over, so nothing can still be waiting on a permission, whether or not a prompt is waiting on the turn.
405	    session.stopping = false;
406	    await this.dropPendingApproval(session, false);
407	    if (!pending) { session.tools = []; return; }
408	    // From here the prompt is being answered. It stops being cancellable now, before the receipt is awaited: a
409	    // $/cancel_request in that window would otherwise answer it a second time and wait for a turn that has ended.
410	    session.pendingPrompt = undefined;
411	    session.tools = [];
412	    const resultId = `acp-receipt-${pending.commandId}`;
413	    let sections: any[] = [];
414	    try {
415	      const detail = await new Promise<SidecarEvent | undefined>((resolve) => {
416	        const timer = setTimeout(() => { if (session.pendingReceipt?.commandId === resultId) session.pendingReceipt = undefined; resolve(undefined); }, 2_000);
417	        session.pendingReceipt = { commandId: resultId, resolve: (value) => { clearTimeout(timer); resolve(value); } };
418	        void this.sidecarCommand(session, { type: "receipt", id: resultId });
419	      });
420	      if (detail?.type === "receipt") sections = detail.sections;
421	    } catch { /* A missing receipt is represented as missing evidence, never as a passed verifier. */ }
422	    const turnId = event.turn_id ?? null;
423	    const verification: AcpVerification = verificationFromTurn({ sessionId: session.id, turnId, turn: event.turn, sections });
424	    const receipt = nexusReceipt(session.id, verification, sections);
425	    this.receipts.set(receipt.receipt_id, receipt);
426	    while (this.receipts.size > ACP_RECEIPT_STORE_SIZE) this.receipts.delete(this.receipts.keys().next().value as string);
427	    const mapped = turnToStop(event.turn);
428	    this.send(sessionUpdate(session.id, verificationUpdate(verification) as any));
429	    this.send(sessionUpdate(session.id, verdictChunk(event.heading, event.line)));
430	    if ("error" in mapped) this.replyError(pending.rpcId, mapped.error);
431	    else this.send(resultResponse(pending.rpcId, promptResult(mapped.stopReason, verification)));
432	    this.pending.delete(this.requestKey(pending.rpcId));
433	  }
434	}
435	
436	/**
437	 * Why `nexus acp` must not start with this configuration, or undefined. Only review and read-only are served: the
438	 * client on the other end is untrusted, and auto approval would let every tool call through without asking it.
439	 */
440	export function acpStartupRefusal(config: Pick<HarnessConfig, "approvalMode" | "fullAccess">): string | undefined {
441	  if (config.approvalMode !== "auto" && !config.fullAccess) return undefined;
442	  return "nexus acp does not run with automatic approval (--yes, --mode auto or NEXUS_APPROVAL_MODE=auto). Start it in review mode (the default) or with --read-only.";
443	}
444	
445	/** Attach the adapter to process stdio. Stdout is reserved for JSON-RPC messages. */
446	export function runAcpStdio(options: AcpStdioOptions): AcpStdioServer {
447	  const protocolWrite = process.stdout.write.bind(process.stdout);
448	  // ACP owns stdout for the lifetime of this command; incidental logs must never corrupt the wire stream.
449	  (process.stdout as any).write = (_chunk: unknown, encoding?: unknown, callback?: unknown): boolean => {
450	    const done = typeof encoding === "function" ? encoding : callback;
451	    if (typeof done === "function") queueMicrotask(done as () => void);
452	    return true;
453	  };
454	  const server = new AcpStdioServer({ ...options, write: options.write ?? ((line) => protocolWrite(line)) });
455	  process.stdin.on("data", (chunk: Buffer) => server.push(chunk));
456	  process.stdin.once("end", () => { void server.close(); });
457	  // The stdin listener keeps the process alive, so setting an exit code would leave it running after a signal.
458	  // close() waits for every session to stop. A session that never does must not keep a signalled process alive.
459	  const stop = (code: number) => {
460	    setTimeout(() => process.exit(code), options.shutdownGraceMs ?? ACP_SHUTDOWN_GRACE_MS).unref();
461	    void server.close().finally(() => process.exit(code));
462	  };
463	  process.once("SIGINT", () => stop(130));
464	  process.once("SIGTERM", () => stop(143));
465	  return server;
466	}
