24	export type TestCommandExecutor = (command: string) => Promise<{ success: boolean; output: string; error?: string; timedOut?: boolean }>;
25	
26	export const DEFAULT_VERIFIER_TIMEOUT_SECS = 300;
27	
28	export function verifierTimeoutSecs(configured?: number): number {
29	  if (typeof configured === "number" && Number.isFinite(configured) && configured > 0) {
30	    return Math.floor(configured);
31	  }
32	  const envVal = Number(process.env.NEXUS_VERIFIER_TIMEOUT_SECS);
33	  if (Number.isFinite(envVal) && envVal > 0) {
34	    return Math.floor(envVal);
35	  }
36	  return DEFAULT_VERIFIER_TIMEOUT_SECS;
37	}
38	
39	function validateFilterPattern(filterPattern?: string): string | undefined {
40	  if (!filterPattern) return undefined;
41	  // The filter is interpolated into a shell command: letters, digits and `_ : . / -` with single spaces only (no
42	  // newline, quote or shell metacharacter), and it may not start with `-` (it would become a runner flag).
43	  const trimmed = filterPattern.trim();
44	  if (!trimmed) return undefined;
45	  if (!/^[A-Za-z0-9_:./ -]+$/.test(trimmed) || trimmed.startsWith("-")) {
46	    throw new Error(`Invalid test filter pattern '${filterPattern}': contains unsafe characters.`);
47	  }
48	  return trimmed;
49	}
50	
51	/**
52	 * Python tests with no project configuration (no pyproject.toml / setup.py): `test_*.py` files in `tests/` or at the
53	 * root, run with the standard library's unittest (always present, unlike pytest).
54	 */
55	function unittestLayout(root: string): DiscoveredVerifier | null {
56	  const testFiles = (dir: string) => {
57	    try {
58	      return fs.readdirSync(path.join(root, dir)).filter((name) => /^test_.*\.py$/.test(name));
59	    } catch {
60	      return [];
61	    }
62	  };
63	  if (testFiles("tests").length) return { command: "python3 -m unittest discover -s tests", evidence: `tests/${testFiles("tests")[0]}` };
64	  if (testFiles("test").length) return { command: "python3 -m unittest discover -s test", evidence: `test/${testFiles("test")[0]}` };
65	  if (testFiles(".").length) return { command: "python3 -m unittest discover", evidence: testFiles(".")[0] };
66	  return null;
67	}
68	
69	export interface DiscoveredVerifier {
70	  command: string;
71	  /** Repository file that justifies selecting this verifier. */
72	  evidence: string;
73	}
74	
75	/**
76	 * Select a verifier only when repository files justify one. There is no `npm test` fallback:
77	 * a workspace with no applicable verifier has none (returns null).
78	 */
79	export function discoverVerifier(workspace: string, filterPattern?: string): DiscoveredVerifier | null {
80	  const root = path.resolve(workspace);
81	  const filter = validateFilterPattern(filterPattern);
82	  const has = (p: string) => fs.existsSync(path.join(root, p));
83	
84	  if (has("Makefile")) {
85	    try {
86	      if (/^test:/m.test(fs.readFileSync(path.join(root, "Makefile"), "utf-8"))) {
87	        return {
88	          command: filter ? `make test FILTER="${filter}"` : "make test",
89	          evidence: "Makefile:test",
90	        };
91	      }
92	    } catch {}
93	  }
94	  if (has("Cargo.toml")) {
95	    return {
96	      command: filter ? `cargo test -- ${filter}` : "cargo test",
97	      evidence: "Cargo.toml",
98	    };
99	  }

